mod types;

pub use tab_item::TabItem;
pub use types::{IconFactory, TabVariant, TabsTheme};
/// A tabs component with theming support
pub struct Tabs {
    id: ElementId,
    tabs: Vec<TabItem>,
    selected_index: usize,
    variant: TabVariant,
    theme: Option<TabsTheme>,
    on_change: Option<Rc<dyn Fn(usize, &mut Window, &mut App) + 'static>>,
    on_close: Option<Rc<dyn Fn(&SharedString, &mut Window, &mut App) + 'static>>,
    focus_handle: Option<FocusHandle>,
    aria_label: Option<SharedString>,
    aria_role: Option<AriaRole>,
}

impl Tabs {
    /// Create a new tabs component with an ID
    pub fn new(id: impl Into<ElementId>) -> Self {
        Self {
            id: id.into(),
            tabs: Vec::new(),
            selected_index: 0,
            variant: TabVariant::default(),
            theme: None,
            on_change: None,
            on_close: None,
            focus_handle: None,
            aria_label: None,
            aria_role: None,
        }
    }

    /// Set the focus handle for keyboard navigation
    pub fn focus_handle(mut self, handle: FocusHandle) -> Self {
        self.focus_handle = Some(handle);
        self
    }

    /// Set the tab items
    pub fn tabs(mut self, tabs: Vec<TabItem>) -> Self {
        self.tabs = tabs;
        self
    }

    /// Set the selected tab index
    pub fn selected_index(mut self, index: usize) -> Self {
        self.selected_index = index;
        self
    }

    /// Set the visual variant
    pub fn variant(mut self, variant: TabVariant) -> Self {
        self.variant = variant;
        self
    }

    /// Set the theme
    pub fn theme(mut self, theme: TabsTheme) -> Self {
        self.theme = Some(theme);
        self
    }

    /// Set the tab change handler
    pub fn on_change(mut self, handler: impl Fn(usize, &mut Window, &mut App) + 'static) -> Self {
        self.on_change = Some(Rc::new(handler));
        self
    }

    /// Set an explicit ARIA label
    pub fn aria_label(mut self, label: impl Into<SharedString>) -> Self {
        self.aria_label = Some(label.into());
        self
    }

    /// Override the default ARIA role (Tablist)
    pub fn aria_role(mut self, role: AriaRole) -> Self {
        self.aria_role = Some(role);
        self
    }

    /// Set the tab close handler
    pub fn on_close(
        mut self,
        handler: impl Fn(&SharedString, &mut Window, &mut App) + 'static,
    ) -> Self {
        self.on_close = Some(Rc::new(handler));
        self
    }

    /// Build into element with theme
    ///
    /// # Keyboard Navigation
    /// - Left/Right arrows: Navigate between tabs
    /// - Home: Select first tab
    /// - End: Select last tab
    pub fn build_with_theme(
        self,
        global_theme: &crate::theme::Theme,
        cx: &mut App,
    ) -> Stateful<Div> {
        let tabs_theme = TabsTheme::from(global_theme);
        let theme = self.theme.as_ref().unwrap_or(&tabs_theme);

        // Get or create focus handle
        let focus_handle = self.focus_handle.unwrap_or_else(|| cx.focus_handle());

        let mut container = div()
            .id(self.id.clone())
            .font_family(global_theme.font_family.clone())
            .track_focus(&focus_handle)
            .flex()
            .items_center()
            .focusable();

        // Apply variant-specific container styling
        match self.variant {
            TabVariant::Underline => {
                // No border on container - we'll add underlines per-tab
            }
            TabVariant::Enclosed => {
                container = container.gap_1();
            }
            TabVariant::Pills => {
                container = container.gap_2().p_1().bg(theme.container_bg).rounded_lg();
            }
            TabVariant::VerticalCard => {
                container = container
                    .flex_wrap()
                    .gap_2()
                    .p_1()
                    .bg(theme.container_bg)
                    .rounded_lg();
            }
        }

        // Callbacks are already stored as Rc; clone the Option once and reuse for each tab.
        let on_change_rc = self.on_change.clone();
        let on_close_rc = self.on_close.clone();

        // Capture tab count before consuming tabs
        let tab_count = self.tabs.len();

        // Reusable hover closures (allocated once) for each visual branch.
        // They only capture Copy Rgba values, so the closures themselves are Copy
        // and can be passed to .hover() every iteration without per-tab allocation.
        let text_hover = theme.text_hover;
        let hover_bg = theme.hover_bg;
        let selected_bg = theme.selected_bg;
        let close_hover_color = theme.close_hover_color;

        let hover_underline = move |s: StyleRefinement| s.text_color(text_hover);
        let hover_enclosed = move |s: StyleRefinement| {
            s.bg(hover_bg)
                .text_color(text_hover)
                .shadow(glow_shadow(hover_bg))
        };
        let hover_pills = move |s: StyleRefinement| {
            s.bg(selected_bg)
                .text_color(text_hover)
                .shadow(glow_shadow(selected_bg))
        };
        let hover_close = move |s: StyleRefinement| s.text_color(close_hover_color);

        for (index, tab) in self.tabs.into_iter().enumerate() {
            let is_selected = index == self.selected_index;
            let tab_id = tab.id;
            let tab_element_id = tab.tab_element_id;
            let close_element_id = tab.close_element_id;
            let wrapper_element_id = tab.wrapper_element_id;
            let label = tab.label;
            let icon = tab.icon;
            let custom_icon = tab.custom_icon;
            let icon_factory = tab.icon_factory;
            let badge = tab.badge;
            let disabled = tab.disabled;
            let closeable = tab.closeable;

            let on_change = on_change_rc.clone();
            let on_close = on_close_rc.clone();

            // For Underline variant, we wrap the tab content and underline in a flex column
            let tab_element = if self.variant == TabVariant::Underline {
                let mut tab_content = div()
                    .id(tab_element_id)
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_4()
                    .py_2();

                if is_selected {
                    tab_content = tab_content
                        .text_color(theme.text_selected)
                        .font_weight(FontWeight::SEMIBOLD);
                } else {
                    tab_content = tab_content
                        .text_color(theme.text_unselected)
                        .hover(hover_underline);
                }

                if disabled {
                    tab_content = tab_content.opacity(0.5).cursor_not_allowed();
                } else {
                    tab_content = tab_content.cursor_pointer();

                    if let Some(ref handler) = on_change {
                        let idx = index;
                        let handler = handler.clone();
                        tab_content = tab_content.on_mouse_down(
                            MouseButton::Left,
                            move |_event, window, cx| {
                                handler(idx, window, cx);
                            },
                        );
                    }
                }

                // Add icon
                if let Some(custom_icon) = custom_icon {
                    tab_content = tab_content.child(custom_icon);
                } else if let Some(icon) = icon {
                    tab_content = tab_content.child(div().text_sm().child(icon));
                }

                // Add label
                tab_content = tab_content.child(div().text_sm().child(label));

                // Add badge
                if let Some(badge) = badge {
                    tab_content = tab_content.child(
                        div()
                            .text_xs()
                            .px_1()
                            .py(px(1.0))
                            .bg(theme.badge_bg)
                            .rounded(px(3.0))
                            .child(badge),
                    );
                }

                // Add close button
                if closeable {
                    let id = tab_id;
                    let mut close_btn = div()
                        .id(close_element_id)
                        .text_xs()
                        .text_color(theme.close_color)
                        .hover(hover_close);

                    if let Some(ref handler) = on_close {
                        let handler = handler.clone();
                        close_btn = close_btn.on_mouse_down(
                            MouseButton::Left,
                            move |_event, window, cx| {
                                handler(&id, window, cx);
                            },
                        );
                    }

                    tab_content = tab_content.child(close_btn.child("×"));
                }

                // Create the underline - accent color for selected, border color for unselected
                let underline = if is_selected {
                    div().h(px(2.0)).w_full().bg(theme.accent)
                } else {
                    div().h(px(1.0)).w_full().bg(theme.container_border)
                };

                // Wrap in a flex column
                div()
                    .id(wrapper_element_id)
                    .flex()
                    .flex_col()
                    .child(tab_content)
                    .child(underline)
            } else if self.variant == TabVariant::VerticalCard {
                // VerticalCard variant: icon on left (spanning 2 rows), title + number on right
                // +---------------+
                // | ICON | Title  |
                // |      | Number |
                // +---------------+
                let mut tab_el = div()
                    .id(tab_element_id)
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_3()
                    .py_2()
                    .min_w(px(90.0));

                if is_selected {
                    tab_el = tab_el
                        .bg(theme.accent)
                        .rounded_lg()
                        .text_color(theme.text_selected);
                } else {
                    tab_el = tab_el
                        .bg(theme.selected_bg)
                        .rounded_lg()
                        .text_color(theme.text_unselected)
                        .hover(hover_pills);
                }

                if disabled {
                    tab_el = tab_el.opacity(0.5).cursor_not_allowed();
                } else {
                    tab_el = tab_el.cursor_pointer();

                    if let Some(ref handler) = on_change {
                        let idx = index;
                        let handler = handler.clone();
                        tab_el =
                            tab_el.on_mouse_down(MouseButton::Left, move |_event, window, cx| {
                                handler(idx, window, cx);
                            });
                    }
                }

                // Icon on left (large, spans both rows visually)
                // Apply appropriate icon color based on selection state
                let icon_color = if is_selected {
                    theme.icon_selected.unwrap_or(theme.text_selected)
                } else {
                    theme.icon_unselected.unwrap_or(theme.accent)
                };
                // Prefer icon_factory (creates icon with explicit color) over custom_icon
                if let Some(factory) = icon_factory {
                    // Create the icon with the correct color at render time
                    let icon_element = factory(icon_color);
                    tab_el = tab_el.child(div().flex().items_center().child(icon_element));
                } else if let Some(custom_icon) = custom_icon {
                    tab_el = tab_el.child(
                        div()
                            .flex()
                            .items_center()
                            .text_color(icon_color)
                            .child(custom_icon),
                    );
                } else if let Some(icon) = icon {
                    tab_el = tab_el.child(
                        div()
                            .flex()
                            .items_center()
                            .text_xl()
                            .text_color(icon_color)
                            .child(icon),
                    );
                }

                // Right side: Title on top, Number below
                let mut right_col = div().flex().flex_col().gap(px(1.0));

                // Title
                right_col = right_col.child(
                    div()
                        .text_xs()
                        .font_weight(if is_selected {
                            FontWeight::SEMIBOLD
                        } else {
                            FontWeight::NORMAL
                        })
                        .child(label),
                );

                // Number/badge below title
                if let Some(badge) = badge {
                    right_col =
                        right_col.child(div().text_sm().font_weight(FontWeight::BOLD).child(badge));
                }

                tab_el = tab_el.child(right_col);

                tab_el
            } else {
                // Non-underline variants (Enclosed, Pills)
                let mut tab_el = div()
                    .id(tab_element_id)
                    .flex()
                    .items_center()
                    .gap_2()
                    .px_4()
                    .py_2();

                match self.variant {
                    TabVariant::Enclosed => {
                        if is_selected {
                            tab_el = tab_el
                                .bg(theme.selected_bg)
                                .rounded_t_md()
                                .text_color(theme.text_selected);
                        } else {
                            tab_el = tab_el
                                .text_color(theme.text_unselected)
                                .hover(hover_enclosed);
                        }
                    }
                    TabVariant::Pills => {
                        if is_selected {
                            tab_el = tab_el
                                .bg(theme.accent)
                                .rounded_md()
                                .text_color(theme.text_selected);
                        } else {
                            tab_el = tab_el
                                .rounded_md()
                                .text_color(theme.text_unselected)
                                .hover(hover_pills);
                        }
                    }
                    TabVariant::Underline | TabVariant::VerticalCard => unreachable!(),
                }

                if disabled {
                    tab_el = tab_el.opacity(0.5).cursor_not_allowed();
                } else {
                    tab_el = tab_el.cursor_pointer();

                    if let Some(ref handler) = on_change {
                        let idx = index;
                        let handler = handler.clone();
                        tab_el =
                            tab_el.on_mouse_down(MouseButton::Left, move |_event, window, cx| {
                                handler(idx, window, cx);
                            });
                    }
                }

                // Add icon
                if let Some(custom_icon) = custom_icon {
                    tab_el = tab_el.child(custom_icon);
                } else if let Some(icon) = icon {
                    tab_el = tab_el.child(div().text_sm().child(icon));
                }

                // Add label
                tab_el = tab_el.child(div().text_sm().child(label));

                // Add badge
                if let Some(badge) = badge {
                    tab_el = tab_el.child(
                        div()
                            .text_xs()
                            .px_1()
                            .py(px(1.0))
                            .bg(theme.badge_bg)
                            .rounded(px(3.0))
                            .child(badge),
                    );
                }

                // Add close button
                if closeable {
                    let id = tab_id;
                    let mut close_btn = div()
                        .id(close_element_id)
                        .text_xs()
                        .text_color(theme.close_color)
                        .hover(hover_close);

                    if let Some(ref handler) = on_close {
                        let handler = handler.clone();
                        close_btn = close_btn.on_mouse_down(
                            MouseButton::Left,
                            move |_event, window, cx| {
                                handler(&id, window, cx);
                            },
                        );
                    }

                    tab_el = tab_el.child(close_btn.child("×"));
                }

                tab_el
            };

            container = container.child(tab_element);
        }

        // Add keyboard navigation
        let selected = self.selected_index;
        let on_change_key = on_change_rc.clone();
        let focus_handle_key = focus_handle.clone();

        container = container.on_key_down(move |event, window, cx| {
            if !focus_handle_key.is_focused(window) {
                return;
            }

            let key = event.keystroke.key.as_str();
            let new_index = match key {
                "left" => {
                    if selected > 0 {
                        Some(selected - 1)
                    } else {
                        None
                    }
                }
                "right" => {
                    if selected + 1 < tab_count {
                        Some(selected + 1)
                    } else {
                        None
                    }
                }
                "home" => Some(0),
                "end" => {
                    if tab_count > 0 {
                        Some(tab_count - 1)
                    } else {
                        None
                    }
                }
                _ => None,
            };

            if let Some(new_idx) = new_index {
                cx.stop_propagation();
                if let Some(ref handler) = on_change_key {
                    handler(new_idx, window, cx);
                }
            }
        });

        container
    }
}

impl Default for Tabs {
    fn default() -> Self {
        Self::new("tabs")
    }
}

/// Internal entity that renders a [`Tabs`] component. A fresh entity is created
/// on each render so that the tab items (which may contain single-use elements)
/// can be consumed while still rendering through GPUI's entity path.
pub struct TabsEntity {
    props: Tabs,
}

impl Render for TabsEntity {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let id = self.props.id.clone();
        let aria_label = self.props.aria_label.clone();
        let aria_role = self.props.aria_role;
        cx.register_accessible(AccessibilityNode {
            element_id: id,
            label: aria_label.unwrap_or_default(),
            props: AriaProps::with_role(aria_role.unwrap_or(AriaRole::Tablist)),
        });

        let global_theme = cx.theme();
        std::mem::take(&mut self.props).build_with_theme(global_theme.as_ref(), &mut **cx)
    }
}

impl RenderOnce for Tabs {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        cx.new(|_cx| TabsEntity { props: self })
    }
}

impl IntoElement for Tabs {
    type Element = gpui::Component<Self>;

    fn into_element(self) -> Self::Element {
        gpui::Component::new(self)
    }
}
